        public static void Uv(int index, out float scaleX, out float scaleY, out float offX, out float offY)
        {
            if (index < 0) index = 0;
            int col = index % Columns;
            int row = index / Columns;
            float du = 1f / Columns;
            float dv = 1f / Rows;
            float g = 1f / (Columns * CellWidth);
            scaleX = du - g * 2f;
            scaleY = dv - g * 2f;
            offX = col * du + g;
            offY = 1f - (row + 1f) * dv + g;
        }

